create or replace function greenloop_private.verification_node(p_name text,p_values jsonb)returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public as $$
declare spec jsonb;f record;dep text;result text;query text;values_map jsonb:=p_values;state jsonb;
begin
 if values_map?p_name then return values_map;end if;
 spec:=greenloop_private.verification_catalog()->'components'->p_name;
 if spec is null then raise exception 'Unreviewed verification component.'using errcode='22023';end if;
 select p.*,l.lanname into f from pg_proc p join pg_language l on l.oid=p.prolang where p.oid=to_regprocedure(format('public.%I()',p_name));
 if not found then return values_map||jsonb_build_object(p_name,jsonb_build_object('ok',false,'kind','missing-marker','rpc',p_name,'message','Version check is not installed yet.'));end if;
 if md5(replace(replace(f.prosrc,chr(13)||chr(10),chr(10)),chr(13),chr(10))) is distinct from spec->>'hash'or f.pronargs<>0 or f.prorettype<>'text'::regtype or f.proretset or f.prosecdef is distinct from(spec->>'security_definer')::boolean or f.provolatile::text is distinct from spec->>'volatility'or f.lanname is distinct from spec->>'language'or to_jsonb(f.proconfig)is distinct from spec->'settings'
 or not has_function_privilege('anon',f.oid,'EXECUTE')or not has_function_privilege('authenticated',f.oid,'EXECUTE')then
 return values_map||jsonb_build_object(p_name,jsonb_build_object('ok',false,'kind','changed-marker','rpc',p_name,'message','Reviewed verification definition or access changed.'));
 end if;
 for dep in select jsonb_array_elements_text(spec->'dependencies')loop if not values_map?dep then raise exception 'Verification dependency order changed.'using errcode='55000';end if;end loop;
 if f.lanname='sql'then
  query:=f.prosrc;
  for dep in select jsonb_array_elements_text(spec->'dependencies')loop
   query:=regexp_replace(query,'(public\.)?'||dep||'\(\)',format('($1->%L->>''version'')',dep),'g');
  end loop;
  execute query into result using values_map;
 else
  -- The seven legacy PL/pgSQL checks retain their original reviewed loops and guards.
  execute format('select public.%I()',p_name)into result;
 end if;
 state:=case when result is not null then jsonb_build_object('ok',true,'kind','verified','rpc',p_name,'version',result)
 else jsonb_build_object('ok',false,'kind','changed-marker','rpc',p_name,'message','Database integrity checks did not pass.')end;
 return values_map||jsonb_build_object(p_name,state);
exception when others then
 return values_map||jsonb_build_object(p_name,jsonb_build_object('ok',false,'kind','verification-error','rpc',p_name,'code',sqlstate,'message','The reviewed verification component could not be evaluated.'));
end;$$;
revoke all on function greenloop_private.verification_catalog(),greenloop_private.verification_node(text,jsonb)from public,anon,authenticated;
create or replace function public.get_installation_verification_version()returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public as $$
declare values_map jsonb:='{}';name text;
begin
 if not(select count(*)=3 and bool_and(coalesce(hash=md5(pg_get_functiondef(to_regprocedure(identity))),false))from greenloop_private.verification_engine_installation)
 or not exists(select 1 from pg_class where oid='greenloop_private.verification_engine_installation'::regclass and relrowsecurity)
 or has_table_privilege('anon','greenloop_private.verification_engine_installation','SELECT,INSERT,UPDATE,DELETE,TRUNCATE')or has_table_privilege('authenticated','greenloop_private.verification_engine_installation','SELECT,INSERT,UPDATE,DELETE,TRUNCATE')
 or has_function_privilege('anon','greenloop_private.verification_node(text,jsonb)','EXECUTE')or has_function_privilege('authenticated','greenloop_private.verification_node(text,jsonb)','EXECUTE')
 or has_function_privilege('anon','greenloop_private.verification_catalog()','EXECUTE')or has_function_privilege('authenticated','greenloop_private.verification_catalog()','EXECUTE')then
 raise exception 'Verification engine integrity check failed.'using errcode='55000';end if;
 for name in select jsonb_array_elements_text(greenloop_private.verification_catalog()->'order')loop values_map:=greenloop_private.verification_node(name,values_map);end loop;
 return jsonb_build_object('engine_version','20261029-verification-engine-1','versions',values_map);
end;$$;
revoke all on function public.get_installation_verification_version()from public;
grant execute on function public.get_installation_verification_version()to anon,authenticated;
insert into greenloop_private.verification_engine_installation select p.oid::regprocedure::text,md5(pg_get_functiondef(p.oid))from pg_proc p where p.oid in('greenloop_private.verification_catalog()'::regprocedure,'greenloop_private.verification_node(text,jsonb)'::regprocedure,'public.get_installation_verification_version()'::regprocedure)on conflict(identity)do update set hash=excluded.hash;
do $$declare result jsonb;bad text;begin
 result:=public.get_installation_verification_version();
 if(result->'versions'->'get_lab_delay_version'->>'ok')is distinct from 'true'then raise exception 'Existing Lab Delay integrity could not be verified. Repair rolled back.';end if;
 select key into bad from jsonb_each(result->'versions')where value->>'kind'not in('verified','missing-marker')order by key limit 1;
 if bad is not null then raise exception 'Existing integrity check failed: %. Repair rolled back.',bad;end if;
end;$$;
notify pgrst,'reload schema';commit;
select public.get_installation_verification_version()->>'engine_version'as installed_verification_engine_version;
